sig D extends P {}
run { one P and one C and one D and some x:P | x in C and x in D } for 4 Int, 2 P, 1 C, 1 D, 0 seq

abstract sig P {}
sig C extends P {}
sig D extends P {}
run { one P and one C and no D and some x:P+C | x in C and x not in P } for 4 Int, 2 P, 1 C, 1 D, 0 seq

sig A {}
sig B {}
